<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>کالاهای پرفروش</title><link rel="stylesheet" href="{{ asset('css/Vazirmatn.css') }}"><style>body{font-family:Vazirmatn,sans-serif;color:#193c52;margin:24px;font-size:12px}h1{font-weight:500}table{width:100%;border-collapse:collapse}td,th{padding:9px;text-align:right;border-bottom:1px solid #dce6ee}th{background:#eff6fa}img{width:42px;height:42px;object-fit:contain}tr{break-inside:avoid}button{padding:10px}@media print{button{display:none}body{margin:0}thead{display:table-header-group}}@page{size:A4;margin:12mm}</style></head><body><button onclick="window.print()">چاپ / ذخیره PDF</button><h1>کالاهای پرفروش</h1><p>تاریخ ارسال: {{ $filters['date_from'] }} تا {{ $filters['date_to'] }} | معیار: {{ $filters['metric']==='quantity'?'تعداد':'مبلغ' }} | {{ $filters['group']==='product'?'کالا':'تنوع' }}</p><p>تعداد {{ number_format($report['summary']['quantity']) }} · فروش {{ number_format($report['summary']['revenue']) }} ریال · {{ $report['summary']['invoices'] }} فاکتور</p><p>پس از تخفیف؛ بدون هزینهٔ ارسال و کسر مرجوعی. موجودی، مقدار آزادِ فعلی مرکزی است.</p><p>دسته: {{ $filters['category_name'] }} · فروشنده: {{ $filters['seller_name'] }}</p>@if($report['undated_invoices'])<p>{{ $report['undated_invoices'] }} فاکتور ارسال‌شده در کل سوابقِ این فیلترها تاریخ ارسال ندارند و در بازه محاسبه نشده‌اند.</p>@endif<table><thead><tr><th>رتبه</th><th>تصویر</th><th>کالا / تنوع</th><th>تعداد</th><th>مبلغ (ریال)</th><th>سهم</th><th>موجودی فعلی</th></tr></thead><tbody>@foreach($report['rows'] as $r)<tr><td>{{ $loop->iteration }}</td><td>@if($r['image_path'])<img src="{{ route('finance.reports.top-products.image',$r['product_id']) }}" alt="">@endif</td><td>{{ $r['name'] }}<br>{{ $r['variant_name'] }}</td><td>{{ number_format($r['quantity']) }}</td><td>{{ number_format($r['revenue']) }}</td><td>{{ $r['share'] }}٪</td><td>{{ $r['stock']===null?'—':number_format($r['stock']) }}</td></tr>@endforeach</tbody></table><script>window.addEventListener('load',async()=>{if(document.fonts)await document.fonts.ready;window.print()});</script></body></html>
